    spec.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || owner.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || snapshot.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
