function registeredWorktreePaths(gitCwd: string): Set<string> {
  const raw = execFileSync('git', ['worktree', 'list', '--porcelain'], {
    cwd: gitCwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
    maxBuffer: 8 * 1024 * 1024,
