export const CODEX_TURN_FAILED_DIGEST_MAX_CHARS = 160;

/** B-3ddc: depth cap when drilling a JSON-encoded message for the innermost error.message. */
const CODEX_TURN_FAILED_NESTED_DEPTH_CAP = 4;

