   294	function renderManagedReviewerCanonicalReportSnapshot(
   295	  statuses: readonly ManagedReviewCanonicalReportStatus[],
   296	): string[] {
   297	  const byCommand = new Map(statuses.map(status => [status.command, status]));
   298	  if (byCommand.size !== MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.length
   299	    || statuses.length !== MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.length
